# Construct output from observed 28x28 lattice and inferred line-filling rule.
out=[[0]*28 for _ in range(28)]
for r in range(28):
    for c in range(28):
        if r in (4,9,14,19,24) or c in (4,9,14,19,24): out[r][c]=8
# cells are row/column segments bounded by divider indices
rs=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
cs=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
# 3 vertical line through column segment 2, row segments 0..4
for ri in range(5):
    for r in range(*rs[ri]):
        for c in range(*cs[2]): out[r][c]=3
# 2 horizontal line through row segment 1, column segments 0..4
for ci in range(5):
    for r in range(*rs[1]):
        for c in range(*cs[ci]): out[r][c]=2
# 2 vertical line column segment 0, row segments 1..3
for ri in range(1,4):
    for r in range(*rs[ri]):
        for c in range(*cs[0]): out[r][c]=2
# overlap at row segment 1, column segment 2
for r in range(*rs[1]):
    for c in range(*cs[2]): out[r][c]=6
import json
print(json.dumps(out,separators=(',',':')))
